<script lang="ts">
 import {onMount} from 'svelte';
 import {Button} from '$lib/components/ui/button';
 import {Input} from '$lib/components/ui/input';
 import {Textarea} from '$lib/components/ui/textarea';
 import {Sparkles,ChevronDown,Check,Copy,Save,Trash2,RotateCcw} from '@lucide/svelte';
 import {request} from '../api';
 import catalogue from './catalogue.json';
 import {renderPrompt,variableNames,promptBytes} from './render.mjs';
 type Category='story'|'character'|'scene'|'shot'|'asset'|'video';
 type Template={id:string;revision:number;category:string;title_en:string;title_zh:string;body_en:string;body_zh:string;defaults?:Record<string,string>;source_url?:string};
 let {projectId,category='story',onapply,initialValues={}}:{projectId:string;category?:Category;onapply:(text:string,language:'en'|'zh')=>void;initialValues?:Record<string,string>}=$props();
 let open=$state(false),language=$state<'en'|'zh'>('en'),saved=$state<Template[]>([]),selected=$state(''),titleEn=$state(''),titleZh=$state(''),bodyEn=$state(''),bodyZh=$state(''),values=$state<Record<string,string>>({}),error=$state(''),notice=$state(''),busy=$state(false),confirmDelete=$state(false),editTemplate=$state(false);
 const labels:Record<string,string>={subject:'主体 / Character or subject',style:'画风 / Visual style',identity:'辨识特征 / Identity anchors',posture:'体态 / Body & posture',wardrobe:'服装 / Wardrobe',background:'背景 / Background',lighting:'光照 / Lighting',setting:'场景 / Setting',era:'时代地域 / Era & region',weather:'时段与天气 / Time & weather',layout:'空间布局 / Spatial layout',furnishings:'固定陈设 / Furnishings',foreground:'前景 / Foreground',midground:'中景 / Midground',light_source:'光源 / Light source',light_quality:'光线性质 / Light quality',shadows:'反射与阴影 / Reflections & shadows',materials:'材质 / Materials',structure:'结构 / Structure',proportions:'比例 / Proportions',condition:'状态 / Condition',views:'视角 / Views',camera:'镜头 / Camera',action:'动作 / Action',start_state:'起始状态 / Start state',end_state:'结束状态 / End state',audio:'声音方向 / Sound direction',idea:'创意 / Idea',audience:'观众 / Audience',arc:'情绪变化 / Emotional arc'};
 const options=$derived([...catalogue,...saved].filter(t=>t.category===category));
 const chosen=$derived([...catalogue,...saved].find(t=>t.id===selected));
 const text=$derived(language==='en'?bodyEn:bodyZh);
 const names=$derived(variableNames(text));
 const rendered=$derived(renderPrompt(text,values));
 const custom=$derived(!!selected&&!selected.startsWith('builtin:'));
 const tooLong=$derived(promptBytes(bodyEn)>16000||promptBytes(bodyZh)>16000||promptBytes(JSON.stringify(values))>16000);
 const zh=$derived(language==='zh');
 const uid=$props.id();
 function choose(t:Template){selected=t.id;titleEn=t.title_en;titleZh=t.title_zh;bodyEn=t.body_en;bodyZh=t.body_zh;values={...initialValues,...t.defaults};error='';notice='';confirmDelete=false;editTemplate=false;}
 async function load(){try{saved=await request(`/projects/${encodeURIComponent(projectId)}/prompt-templates`);}catch(e){error=(e as Error).message;}}
 onMount(()=>{if(options[0])choose(options[0]);void load();try{language=localStorage.getItem('6eek.prompt-language')==='zh'?'zh':'en';}catch{}});
 function setLanguage(value:'en'|'zh'){language=value;try{localStorage.setItem('6eek.prompt-language',value);}catch{}notice='';}
 async function save(copy=false){if(tooLong){error=zh?'请缩短模板或默认字段内容。':'Shorten the template or its saved defaults.';return;}busy=true;error='';notice='';try{const result=await request(`/projects/${encodeURIComponent(projectId)}/prompt-templates`,{id:custom&&!copy?selected:'',revision:custom&&!copy?chosen?.revision||0:0,category,title_en:titleEn,title_zh:titleZh,body_en:bodyEn,body_zh:bodyZh,defaults:values},'PUT');saved=[result,...saved.filter(t=>t.id!==result.id)];selected=result.id;notice=zh?'模板已保存到此项目。':'Template saved to this project.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function remove(){if(!confirmDelete){confirmDelete=true;return;}busy=true;error='';try{await request(`/projects/${encodeURIComponent(projectId)}/prompt-templates/${encodeURIComponent(selected)}?revision=${chosen?.revision}`,{},'DELETE');saved=saved.filter(t=>t.id!==selected);const first=catalogue.find(t=>t.category===category);if(first)choose(first);notice=zh?'已删除项目模板。':'Project template deleted.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
 function apply(){if(rendered.missing.length||rendered.invalid||!text.trim()||rendered.bytes>8000)return;onapply(rendered.text,language);notice=zh?'提示词已应用。生成前仍需确认积分报价。':'Prompt applied. Review the credit quote before generating.';}
</script>
<section class="prompt-workbench" oninput={event=>event.stopPropagation()}>
 <button class="prompt-trigger" type="button" aria-expanded={open} onclick={()=>open=!open}><Sparkles size={15}/><span>{zh?'提示词与模板':'Prompts & templates'}</span><span class="language-hint">EN / 中文</span><ChevronDown size={14}/></button>
 {#if open}<div class="prompt-content">
 <div class="prompt-language" aria-label="Prompt language"><button type="button" class:active={!zh} aria-pressed={!zh} onclick={()=>setLanguage('en')}>English</button><button type="button" class:active={zh} aria-pressed={zh} onclick={()=>setLanguage('zh')}>简体中文</button></div>
 <label for={`${uid}-template`}>{zh?'选择模板':'Choose a template'}</label><select id={`${uid}-template`} value={selected} onchange={e=>{const t=options.find(t=>t.id===e.currentTarget.value);if(t)choose(t);}} disabled={busy}>{#each options as t}<option value={t.id}>{t.id.startsWith('builtin:')?'':(zh?'我的 · ':'Mine · ')}{(zh?t.title_zh:t.title_en)||(zh?t.title_en:t.title_zh)}</option>{/each}</select>
 {#if !text.trim()}<p class="prompt-note">{zh?'此模板尚未提供中文版，请填写或切换语言。':'This template has no English version yet. Add one or switch language.'}</p>{/if}
 <div class="prompt-variables">{#each names as name}<div><label for={`${uid}-${name}`}>{labels[name]||name.replaceAll('_',' ')}</label><Textarea id={`${uid}-${name}`} rows={name==='idea'||name==='subject'?3:2} value={values[name]||''} maxlength={2000} oninput={e=>{values={...values,[name]:e.currentTarget.value};notice='';}} placeholder={zh?'填写已确认的内容…':'Add confirmed details…'}/></div>{/each}</div>
 <button type="button" class="text-control" aria-expanded={editTemplate} onclick={()=>editTemplate=!editTemplate}>{zh?'编辑模板文本与名称':'Edit template text & names'}<ChevronDown size={13}/></button>
 {#if editTemplate}<div class="prompt-template-edit"><label for={`${uid}-title-en`}>English name</label><Input id={`${uid}-title-en`} bind:value={titleEn} maxlength={120}/><label for={`${uid}-title-zh`}>中文名称</label><Input id={`${uid}-title-zh`} bind:value={titleZh} maxlength={60}/><label for={`${uid}-body`}>{zh?'模板文本 · 使用 {{subject}} 变量':'Template text · use {{subject}} variables'}</label><Textarea id={`${uid}-body`} rows={8} value={text} maxlength={8000} oninput={e=>{if(zh)bodyZh=e.currentTarget.value;else bodyEn=e.currentTarget.value;notice='';}}/><p class="prompt-note">{zh?'英文和中文分别编辑；不会自动翻译自定义内容。保存时会记住当前字段默认值。':'Edit each language separately. Custom text is not translated automatically. Saved presets remember these field defaults.'}</p>{#if tooLong}<p class="prompt-error">{zh?'每个语言版本和默认字段需小于16 KB。':'Each language and saved defaults must stay below16 KB.'}</p>{/if}<div class="prompt-tools"><Button type="button" variant="outline" size="sm" disabled={busy||tooLong||(!bodyEn.trim()&&!bodyZh.trim())} onclick={()=>save()}><Save size={13}/>{custom?(zh?'保存更改':'Save changes'):(zh?'另存为我的模板':'Save my template')}</Button>{#if custom}<Button type="button" variant="ghost" size="sm" disabled={busy||tooLong} onclick={()=>save(true)}>{zh?'保存副本':'Save copy'}</Button><Button type="button" variant="ghost" size="sm" disabled={busy} onclick={remove}><Trash2 size={13}/>{confirmDelete?(zh?'确认删除':'Confirm delete'):(zh?'删除':'Delete')}</Button>{/if}</div></div>{/if}
 <details class="prompt-preview"><summary>{zh?'最终提示词预览':'Final prompt preview'} <span>{rendered.bytes}/8,000 bytes</span></summary><pre lang={zh?'zh-CN':'en'}>{rendered.text||'—'}</pre></details>
 {#if rendered.invalid}<p class="prompt-error" role="alert">{zh?'存在未支持的变量。请使用 {{name}} 格式，不要使用未绑定的参考编号。':'Unsupported placeholder. Use {{name}} variables; unbound reference numbers are not supported.'}</p>{:else if rendered.missing.length}<p class="prompt-note">{zh?'请填写':'Complete'} {rendered.missing.length} {zh?'个字段后应用。':'fields to apply.'}</p>{/if}
 {#if rendered.bytes>8000}<p class="prompt-error" role="alert">{zh?'最终提示词需少于8,000字节。':'Keep the final prompt below8,000 bytes.'}</p>{/if}
 <div class="prompt-tools"><Button type="button" size="sm" disabled={busy||!text.trim()||!!rendered.missing.length||rendered.invalid||rendered.bytes>8000} onclick={apply}><Check size={14}/>{zh?'应用提示词':'Apply prompt'}</Button><Button type="button" variant="ghost" size="sm" disabled={!text.trim()||!!rendered.missing.length||rendered.invalid} onclick={async()=>{try{await navigator.clipboard.writeText(rendered.text);notice=zh?'已复制。':'Copied.';}catch{error=zh?'无法复制，请从预览中选择文字。':'Unable to copy. Select text in the preview.';}}}><Copy size={13}/>{zh?'复制':'Copy'}</Button><Button type="button" variant="ghost" size="icon-sm" aria-label="Refresh saved templates" disabled={busy} onclick={load}><RotateCcw size={13}/></Button></div>
 <p class="prompt-note">{zh?'模板本身不会生成媒体或扣积分。人物参考目前以文字形式传入，不会自动附加图像。':'Templates do not generate media or spend credits. Character references are text directions; images are not attached automatically.'}</p>
 {#if chosen?.source_url}<p class="prompt-source"><a href={chosen.source_url} target="_blank" rel="noreferrer">Toonflow source</a> · <a href="/licenses/toonflow-MIT.txt" target="_blank" rel="noreferrer">MIT / HBAI-Ltd</a></p>{/if}
 {#if notice}<p role="status" class="prompt-success">{notice}</p>{/if}{#if error}<p role="alert" class="prompt-error">{error}</p>{/if}
 </div>{/if}
</section>
<style>
.prompt-workbench{border:1px solid var(--border);border-radius:10px;min-width:0;background:var(--card)}.prompt-trigger{display:flex;align-items:center;gap:9px;width:100%;padding:12px;text-align:left;font-size:12px;font-weight:500}.prompt-trigger>:global(svg:first-child){color:var(--primary)}.language-hint{margin-left:auto;font-size:10px;color:var(--muted-foreground);white-space:nowrap}.prompt-content{display:grid;gap:11px;padding:0 12px 14px}.prompt-content label{font-size:11px;font-weight:500;display:block;line-height:1.6}.prompt-content select{width:100%;min-width:0;height:36px;border:1px solid var(--input);border-radius:6px;background:var(--background);padding:0 8px;font-size:12px}.prompt-language{display:flex;gap:4px;padding:3px;background:var(--muted);border-radius:7px}.prompt-language button{flex:1;padding:6px;font-size:11px;border-radius:5px;color:var(--muted-foreground)}.prompt-language button.active{background:var(--background);color:var(--foreground)}.prompt-variables{display:grid;gap:12px}.prompt-variables>div{display:grid;gap:5px}.prompt-content :global(textarea){font-size:12px;line-height:1.7;min-height:58px}.text-control{font-size:11px;text-align:left;display:flex;align-items:center;justify-content:space-between;color:var(--muted-foreground);padding:6px 0}.prompt-template-edit{display:grid;gap:8px;border-top:1px solid var(--border);padding-top:12px}.prompt-tools{display:flex;align-items:center;gap:5px;flex-wrap:wrap}.prompt-preview{border-top:1px solid var(--border);padding-top:10px}.prompt-preview summary{cursor:pointer;font-size:11px}.prompt-preview summary span{float:right;color:var(--muted-foreground);font-variant-numeric:tabular-nums}.prompt-preview pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;font-size:11px;line-height:1.8;max-height:280px;overflow:auto;padding:12px 0}.prompt-note,.prompt-source{font-size:10px;line-height:1.8;color:var(--muted-foreground);margin:0}.prompt-source a{text-decoration:underline;text-underline-offset:3px}.prompt-error{font-size:11px;line-height:1.7;color:var(--destructive);overflow-wrap:anywhere}.prompt-success{font-size:11px;line-height:1.7;color:var(--foreground)}button:focus-visible,summary:focus-visible{outline:2px solid var(--ring);outline-offset:3px}@media(max-width:767px){.prompt-trigger{min-height:44px}.prompt-language button{min-height:38px}}
</style>
